-- 0153 — Séances fantômes : purge des jours sans séance, réécriture des séances recopiées (2026-10-12).
--
-- CAUSE (corrigée) : jusqu'au 2026-09-21, runIntraday datait la page brvm.org — qui
-- ne porte AUCUNE date — avec « aujourd'hui ». Week-ends, fériés et jours où la page
-- restait figée : la séance précédente était écrite sous la date du jour, puis
-- recopiée par les jobs dérivés. Garde preuveDeSeance (21/09) + jourOuvre (cette PR,
-- qui ferme aussi runObligations, resté ouvert).
--
-- PREUVES : rapprochement ligne à ligne de 4 747 lignes (47 valeurs, 01/05→20/09)
-- avec l'historique public RichBourse — 4 079 concordantes, 0 séance manquante.
--  (A) 6 dates sans séance, 47 lignes chacune : week-ends 31/05, 13/06, 09/08, 29/08 ;
--      07/08 (Indépendance CI, déjà dans market_calendar) ; 25/08 (Maouloud, absent
--      du calendrier, ajouté ici). Lignes = copie exacte de la veille.
--  (B) 374 lignes de 8 vraies séances recopiées de la veille. Valeurs RichBourse,
--      RECOUPÉES 373/374 par le cours_precedent que brvm.org donne à la séance
--      suivante (0 désaccord ; 1 sans lendemain exploitable).
--  Laissées : 12 lignes isolées (volume 0, cours inchangé) absentes de RichBourse —
--  non prouvées fausses. Dérivés des dates (B) (signaux, indicateurs historiques)
--  non recalculés : les jobs glissants se recalculent seuls.
--
-- RÉVERSIBLE : toutes les lignes touchées sont copiées d'abord dans le schéma privé
-- `sauvegarde` (non exposé par l'API, aucun droit pour anon/authenticated).
begin;

create schema if not exists sauvegarde;
revoke all on schema sauvegarde from public, anon, authenticated;

create table sauvegarde.signals_daily_fantomes_20261012 as select * from public.signals_daily where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
create table sauvegarde.technical_indicators_fantomes_20261012 as select * from public.technical_indicators where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
create table sauvegarde.liquidity_daily_fantomes_20261012 as select * from public.liquidity_daily where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
create table sauvegarde.brvm_obligations_daily_fantomes_20261012 as select * from public.brvm_obligations_daily where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
create table sauvegarde.brvm_intraday_snapshots_fantomes_20261012 as select * from public.brvm_intraday_snapshots where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
create table sauvegarde.brvm_indices_daily_fantomes_20261012 as select * from public.brvm_indices_daily where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
create table sauvegarde.brvm_intraday_patterns_fantomes_20261012 as select * from public.brvm_intraday_patterns where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
create table sauvegarde.brvm_pattern_scores_fantomes_20261012 as select * from public.brvm_pattern_scores where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
create table sauvegarde.advisor_history_fantomes_20261012 as select * from public.advisor_history where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
create table sauvegarde.brief_daily_fantomes_20261012 as select * from public.brief_daily where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
create table sauvegarde.brvm_market_summary_fantomes_20261012 as select * from public.brvm_market_summary where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
create table sauvegarde.brvm_actions_daily_fantomes_20261012 as select * from public.brvm_actions_daily where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
create table sauvegarde.brvm_actions_daily_recopiees_20261012 as select * from public.brvm_actions_daily where date_marche in ('2026-06-02','2026-06-04','2026-08-11','2026-08-13','2026-08-17','2026-08-20','2026-08-24','2026-09-14');

-- (A) jours sans séance : dérivés d'abord, cours ensuite.
