delete from public.brief_daily where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
delete from public.brvm_market_summary where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');
delete from public.brvm_actions_daily where date_marche in ('2026-05-31','2026-06-13','2026-08-07','2026-08-09','2026-08-25','2026-08-29');

-- Le Maouloud 2026 manquait au calendrier : c'est ce qui a laissé passer le 25/08.
insert into public.market_calendar (date, is_trading_day, holiday_name, notes)
values ('2026-08-25', false, 'Maouloud', 'Aucune séance (historique RichBourse) ; ajouté par 0153')
on conflict (date) do nothing;

